CREATE TABLE users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'USER',status TEXT NOT NULL DEFAULT 'ACTIVE',marketing_consent INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL);
CREATE TABLE categories (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE products (id TEXT PRIMARY KEY,seller_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL,category_id TEXT NOT NULL REFERENCES categories(id),condition TEXT NOT NULL,price_kurus INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING_REVIEW',location TEXT NOT NULL,image_key TEXT,rejection_reason TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE favorites (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,created_at TEXT NOT NULL,PRIMARY KEY(user_id,product_id));
CREATE TABLE orders (id TEXT PRIMARY KEY,buyer_id TEXT NOT NULL REFERENCES users(id),seller_id TEXT NOT NULL REFERENCES users(id),product_id TEXT NOT NULL REFERENCES products(id),product_title TEXT NOT NULL,product_price_kurus INTEGER NOT NULL,platform_fee_kurus INTEGER NOT NULL,seller_net_amount_kurus INTEGER NOT NULL,payment_status TEXT NOT NULL DEFAULT 'HELD',order_status TEXT NOT NULL DEFAULT 'SELLER_PREPARING',shipping_status TEXT NOT NULL DEFAULT 'NOT_READY',shipping_company TEXT,tracking_number TEXT,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE messages (id TEXT PRIMARY KEY,sender_id TEXT NOT NULL REFERENCES users(id),receiver_id TEXT NOT NULL REFERENCES users(id),product_id TEXT REFERENCES products(id),order_id TEXT REFERENCES orders(id),body TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT);
CREATE TABLE disputes (id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),opened_by TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL);
CREATE TABLE reviews (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),reviewer_id TEXT NOT NULL REFERENCES users(id),reviewed_user_id TEXT NOT NULL REFERENCES users(id),rating INTEGER NOT NULL,comment TEXT,created_at TEXT NOT NULL,UNIQUE(order_id,reviewer_id));
CREATE TABLE cookie_consents (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,anonymous_id TEXT,analytics INTEGER NOT NULL,marketing INTEGER NOT NULL,policy_version TEXT NOT NULL,ip_address TEXT,user_agent TEXT,created_at TEXT NOT NULL);
CREATE TABLE legal_documents (id TEXT PRIMARY KEY,type TEXT NOT NULL,version TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,published_at TEXT NOT NULL,UNIQUE(type,version));
CREATE TABLE legal_acceptances (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,document_id TEXT NOT NULL REFERENCES legal_documents(id),accepted_at TEXT NOT NULL,ip_address TEXT,user_agent TEXT,PRIMARY KEY(user_id,document_id));
CREATE TABLE platform_settings (id INTEGER PRIMARY KEY,commission_type TEXT NOT NULL DEFAULT 'PERCENTAGE',percentage_basis_points INTEGER NOT NULL DEFAULT 500,fixed_fee_kurus INTEGER NOT NULL DEFAULT 0,minimum_fee_kurus INTEGER NOT NULL DEFAULT 0,maximum_fee_kurus INTEGER,maintenance_mode INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,old_value TEXT,new_value TEXT,ip_address TEXT,user_agent TEXT,created_at TEXT NOT NULL);
CREATE TABLE data_requests (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL);
CREATE INDEX idx_sessions_token_expires ON sessions(token_hash,expires_at);
CREATE INDEX idx_products_status_created ON products(status,created_at DESC);
CREATE INDEX idx_products_seller ON products(seller_id,created_at DESC);
CREATE INDEX idx_orders_buyer ON orders(buyer_id,created_at DESC);
CREATE INDEX idx_orders_seller ON orders(seller_id,created_at DESC);
CREATE INDEX idx_messages_participants ON messages(receiver_id,sender_id,created_at DESC);
CREATE INDEX idx_consents_user ON cookie_consents(user_id,created_at DESC);
